package com.gameaggregator.buildservice.api;import jakarta.validation.constraints.*;import java.util.UUID;public final class BuildDtos{private BuildDtos(){}public record Create(@NotNull UUID versionId,@NotNull UUID uploadedBy,String metadataJson){}public record Presign(@NotBlank String fileName,@NotBlank String contentType,@Positive long fileSize,@Pattern(regexp="[a-fA-F0-9]{64}")String checksumSha256){}public record UploadUrl(String objectKey,String uploadUrl,long expiresInSeconds){}public record Complete(@NotBlank String objectKey,@NotBlank String contentType,@Positive long fileSize,@Pattern(regexp="[a-fA-F0-9]{64}")String checksumSha256){}public record Status(@Pattern(regexp="PENDING|UPLOADING|VALIDATING|SUCCEEDED|FAILED|CANCELLED")String status){}public record Log(@Pattern(regexp="DEBUG|INFO|WARN|ERROR")String level,@NotBlank String message){}}